import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { dueCents, hundredths, roundTenThousandths } from '../rates/useRates';

/** Where a claim is in its life: DRAFT → OPEN → SETTLED (or, settled by a clerk over the clerk
 *  limit, OPEN → PENDING, which a steward approves to SETTLED or rejects back to OPEN), and DRAFT,
 *  OPEN or PENDING → VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** Whether a claim is still open: OPEN or PENDING. A PENDING claim is handled like an OPEN one: it
 *  goes overdue, bears the late charge, and a hold takes it out of the totals. */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** A claim as the server sends it: `amount` with two decimals, `date` as yyyy-mm-dd. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** Given when the claim is opened (a voided claim keeps it); null for a DRAFT, or a claim voided while a DRAFT. Sheet-wide ("7"), or within its period ("P1-2", "X-1" in no period). */
  number: string | null;
  /** The due fixed when the claim was settled, two decimals; null when it has none, so its due is live. */
  due: string | null;
  /** The user who opened the claim; null while it has not been opened. */
  openedBy: string | null;
  /** Whether the person's last statement binds the claim to the figure it had then. */
  stated: boolean;
  /** The figure the last statement bound the claim to, two decimals; null when unbound or bound to n/a. */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null for any other claim. */
  corrects: string | null;
  /** Whether the claim's live figures (its rate step and late charge) round half up, else half to
   *  even: half up when it is dated before the sheet's policy date (a correction goes by the date of
   *  the claim it corrects). */
  halfUp: boolean;
};

export const claimsKey = (sheet: string) => ['sheet', sheet, 'claims'] as const;

/** Every claim on the sheet, newest first, re-read whenever the sheet is loaded. */
export function useClaims(sheet: string) {
  return useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    staleTime: 0,
    gcTime: 0,
  });
}

/** An amount the server accepts: up to two decimals; negative only for a correction. */
export const AMOUNT = /^-?\d+(\.\d{1,2})?$/;

/** A correction's `corrects`: the number of the claim it corrects. */
export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;

/** Whether a claim is a correction: its amount is negative. Its due has no floor and no late charge. */
export function isCorrection(claim: Claim): boolean {
  return claim.amount.startsWith('-');
}

/** The claims that count toward claimed, due-total and every total: OPEN, PENDING and SETTLED ones. */
export function counted(claims: Claim[]): Claim[] {
  return claims.filter((c) => isOpen(c) || c.status === 'SETTLED');
}

/** The claims that count in the live totals: OPEN, PENDING and SETTLED ones, but not the OPEN or
 *  PENDING ones of a held person (`held` tells, by person id). */
export function live(claims: Claim[], held: (personId: number) => boolean): Claim[] {
  return counted(claims).filter((c) => !isOpen(c) || !held(c.personId));
}

/** The sum of these claims' amounts, with two decimals. Added up in cents, so it is exact. */
export function claimed(claims: Claim[]): string {
  const cents = claims.reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** What is due on one claim, in cents: the due fixed when it was settled, or else the figure its
 *  person's last statement bound it to, or else live at `pct`, at least the sheet's `floor` (null,
 *  n/a, when there is no rate). */
export function claimDueCents(claim: Claim, floor: string, pct: string | undefined, late?: Late): bigint | null {
  if (claim.due !== null) return hundredths(claim.due);
  const figure = claimFigureCents(claim, floor, pct);
  if (figure === null || late === undefined) return figure;
  return figure + lateChargeCents(claim, figure, late);
}

/** A claim's figure without any late charge, in cents: the figure its person's last statement bound
 *  it to, or else live at `pct`, at least the sheet's `floor` (null, n/a, when there is no rate).
 *  A PENDING claim is not bound by a statement: it shows its live figure. */
function claimFigureCents(claim: Claim, floor: string, pct: string | undefined): bigint | null {
  if (claim.stated && claim.status !== 'PENDING') return claim.statedDue !== null ? hundredths(claim.statedDue) : null;
  const due = dueCents(claim.amount, pct, claim.halfUp);
  if (due === null) return null;
  const least = hundredths(floor);
  return due < least && !isCorrection(claim) ? least : due;
}

/** What makes an overdue claim's due grow: the sheet's `terms`, its `today` and its late percent `pct`. */
export type Late = { terms: number; today: string; pct: string };

/** Whole days from one yyyy-mm-dd to another. */
function daysBetween(from: string, to: string): number {
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000);
}

/** The late charge on an overdue claim's `figure`, in cents: the late percent of it for every full
 *  30 days it is overdue, rounded by the claim's rounding (`halfUp`). Nothing while it is not overdue. Never bound by a
 *  statement: it follows the sheet's today. */
export function lateChargeCents(claim: Claim, figure: bigint, late: Late): bigint {
  if (!overdue(claim, late.terms, late.today) || isCorrection(claim)) return 0n;
  const periods = BigInt(Math.floor(daysBetween(dueBy(claim, late.terms), late.today) / 30));
  if (periods <= 0n) return 0n;
  // cents * hundredths-of-a-percent is in ten-thousandths of a cent.
  const product = figure * hundredths(late.pct) * periods;
  return roundTenThousandths(product, claim.halfUp);
}


/** A person's due-total, in cents: the sum of their counted claims' figures, each already rounded —
 *  a settled claim's fixed due, else the figure a statement bound it to, else live (at least `floor`) at `pctOn(claim's date)`, the rate in force on the claim's
 *  date (at `pct`, the rate in force on the sheet's today, when no `pctOn` is given). 0 with
 *  nothing that counts. With `late`, an overdue claim's late charge is added on top. Null (n/a) when there is no rate today, unless some settled claim keeps a
 *  figure: then it is the sum of the figures there are. */
export function personDueCents(claims: Claim[], floor: string, pct: string | undefined, pctOn?: (date: string) => string | undefined, late?: Late): bigint | null {
  let sum = 0n;
  let any = false;
  for (const c of counted(claims)) {
    const due = claimDueCents(c, floor, pctOn ? pctOn(c.date) : pct, late);
    if (due === null) continue;
    sum += due;
    any = true;
  }
  return pct === undefined && !any ? null : sum;
}

/** A claim's due-by (yyyy-mm-dd): its date plus the sheet's `terms` in days. */
export function dueBy(claim: Claim, terms: number): string {
  const d = new Date(`${claim.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN (or PENDING) and its due-by is before the sheet's `today`. */
export function overdue(claim: Claim, terms: number, today: string): boolean {
  return isOpen(claim) && today !== '' && dueBy(claim, terms) < today;
}

/** These claims' overdue ones: their count, and their dues with late charges added up in cents (n/a ones skipped).
 *  `pctOn` is the rate in force on a claim's date. */
export function overdueFigures(claims: Claim[], late: Late, floor: string, pctOn: (date: string) => string | undefined): { count: number; cents: bigint } {
  const over = claims.filter((c) => overdue(c, late.terms, late.today));
  const cents = over.reduce<bigint>((sum, c) => sum + (claimDueCents(c, floor, pctOn(c.date), late) ?? 0n), 0n);
  return { count: over.length, cents };
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { gradeOn, type Person } from '../people/usePeople';
import { periodOf, usePeriods } from '../periods/usePeriods';
import { rateOn, showDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { useSelectedClaims } from '../bulk/useSelectedClaims';
import {
  AMOUNT,
  CLAIM_NUMBER,
  claimDueCents,
  claimed,
  claimsKey,
  dueBy,
  live,
  overdue,
  overdueFigures,
  personDueCents,
  useClaims,
  type Claim,
} from './useClaims';

const STATUS_REFUSED = "This claim's status cannot change that way (whoever opened a claim cannot settle it).";
const OVER_LIMIT = "A clerk cannot settle a claim whose due is over the sheet's clerk limit.";
const NOT_STEWARD = 'Only a steward can approve a pending claim, and never the user who opened it.';
const NO_REASON = 'A rejection needs a reason.';
const NOT_DRAFT = 'Only a DRAFT claim can be edited: to change an open claim, void it and add a new one.';

const ACTIONS = ['open', 'settle', 'approve', 'reject', 'void'] as const;
type Action = (typeof ACTIONS)[number];
const ACTION_LABELS: Record<Action, string> = { open: 'Open', settle: 'Settle', approve: 'Approve', reject: 'Reject', void: 'Void' };

/**
 * A person's claims: what they have claimed in all and their due-total, the sum of their claims' rounded dues,
 * one form to add a claim or edit the one whose editor is open (only a DRAFT can be edited), and the claims, newest first, each
 * with its period (the one whose dates contain its date, if any), its due (fixed once it is settled, else bound by the last statement, else at the rate in force on the claim's date, at least the sheet's floor; in the
 * due-total too), its status, who opened it, whether a statement binds it and the buttons to open, settle, approve, reject (with a reason) or void it (its opener cannot settle
 * or approve it). A clerk's settle over the clerk limit leaves the claim PENDING until a steward approves
 * or rejects it; while PENDING it shows its live figure, not the one a statement bound it to.
 * Only OPEN, PENDING and SETTLED claims count toward claimed and the due-total, and not the OPEN or
 * PENDING ones while the person is held.
 * A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the person
 * that it corrects (refused otherwise), shows that number, and its due has no floor and no late charge.
 * Each claim shows its due-by (its date plus the sheet's terms) and whether it is overdue (OPEN and
 * due by before the sheet's today); the person shows how many of the claims that count are overdue
 * and their dues added up.
 */
function PersonClaims({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: all = [] } = useClaims(sheet);
  const claims = all.filter((c) => c.personId === person.id);
  // While the person is held, their OPEN and PENDING claims count toward neither claimed nor the due-total.
  const liveClaims = live(claims, () => person.held);
  const { data: rates = [] } = useRates(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const today = useSheetToday(sheet);
  const pct = rateOn(rates, gradeOn(person, today), today);
  const floor = useFloor(sheet);
  const lateBy = useLate(sheet);
  const terms = lateBy.terms;
  const late = overdueFigures(liveClaims, lateBy, floor, (d) => rateOn(rates, gradeOn(person, d), d));
  const [editing, setEditing] = useState<number | null>(null);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [note, setNote] = useState('');
  const [corrects, setCorrects] = useState('');
  const [invalid, setInvalid] = useState(false);
  // The claim whose last status change or edit was refused: its row shows the error.
  const [refused, setRefused] = useState<{ id: number; message: string } | null>(null);
  // The claims ticked for a bulk action (the bulk-open panel acts on them).
  const [selected, setSelected] = useSelectedClaims();
  // The reason typed for rejecting each pending claim, by claim id.
  const [reasons, setReasons] = useState<Record<number, string>>({});
  const base = `/api/sheets/${encodeURIComponent(sheet)}`;

  const submitOnce = useSubmitOnce();
  const save = useMutation({
    mutationFn: (c: { id: number | null; amount: string; date: string; note: string; corrects: string }) => {
      const body = { amount: c.amount, date: c.date, note: c.note, corrects: c.corrects, user };
      return c.id === null
        ? postJson<Claim>(`${base}/people/${person.id}/claims`, body)
        : putJson<Claim>(`${base}/claims/${c.id}`, body);
    },
    onSuccess: async () => {
      close();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    // An edit of a claim no longer a DRAFT is refused on the claim itself; the editor stays open.
    onError: async (e, c) => {
      if (c.id !== null && e instanceof HttpError && e.status === 409 && e.body.includes('DRAFT')) {
        setRefused({ id: c.id, message: NOT_DRAFT });
        await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
      }
    },
  });

  const changeStatus = useMutation({
    mutationFn: (c: { id: number; action: Action; reason?: string }) =>
      postJson<Claim>(`${base}/claims/${c.id}/status`, { action: c.action, user, reason: c.reason }),
    onMutate: () => setRefused(null),
    onSuccess: (_, c) => {
      if (c.action === 'reject') setReasons((r) => ({ ...r, [c.id]: '' }));
    },
    onError: (e, c) =>
      setRefused({
        id: c.id,
        message: !(e instanceof HttpError)
          ? STATUS_REFUSED
          : e.body.includes('clerk limit')
            ? OVER_LIMIT
            : e.body.includes('approve')
              ? NOT_STEWARD
              : e.body.includes('reason')
                ? NO_REASON
                : STATUS_REFUSED,
      }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
  });

  // An error goes as soon as its form is changed or submitted again, or an editor is opened.
  const clearError = () => {
    save.reset();
    setInvalid(false);
    setRefused(null);
  };
  const close = () => {
    setEditing(null);
    setAmount('');
    setDate('');
    setNote('');
    setCorrects('');
  };
  const open = (c: Claim) => {
    clearError();
    // Only a DRAFT can be edited: to change an open claim, void it and add a new one.
    if (c.status !== 'DRAFT') {
      cancel();
      setRefused({ id: c.id, message: NOT_DRAFT });
      return;
    }
    setEditing(c.id);
    setAmount(c.amount);
    setDate(c.date);
    setNote(c.note);
    setCorrects(c.corrects === null ? '' : String(c.corrects));
  };
  const cancel = () => {
    clearError();
    close();
  };

  return (
    <>
      <td data-testid="person-claimed">{claimed(liveClaims)}</td>
      <td data-testid="person-due-total">{showDue(personDueCents(liveClaims, floor, pct, (d) => rateOn(rates, gradeOn(person, d), d), lateBy))}</td>
      <td data-testid="person-overdue-count">{late.count}</td>
      <td data-testid="person-overdue-total">{showDue(late.cents)}</td>
      <td>
        <form
          data-testid="claim-form"
          onSubmit={(e) => {
            e.preventDefault();
            // A negative amount is a correction: it must name the number of the claim it corrects.
            if (!AMOUNT.test(amount.trim()) || (amount.trim().startsWith('-') && !CLAIM_NUMBER.test(corrects.trim()))) {
              // Refused here, before anything is sent: the store is untouched.
              save.reset();
              setInvalid(true);
              return;
            }
            setInvalid(false);
            submitOnce(() => save.mutateAsync({ id: editing, amount: amount.trim(), date: date.trim(), note, corrects: corrects.trim() }));
          }}
        >
          <input
            data-testid="claim-form-amount"
            aria-label="Amount"
            placeholder="0.00"
            value={amount}
            onChange={(e) => {
              setAmount(e.target.value);
              clearError();
            }}
          />{' '}
          <input
            data-testid="claim-form-date"
            aria-label="Date"
            placeholder="yyyy-mm-dd"
            value={date}
            onChange={(e) => {
              setDate(e.target.value);
              clearError();
            }}
          />{' '}
          <input
            data-testid="claim-form-note"
            aria-label="Note"
            placeholder="note"
            value={note}
            onChange={(e) => {
              setNote(e.target.value);
              clearError();
            }}
          />{' '}
          <input
            data-testid="claim-form-corrects"
            aria-label="Corrects claim number"
            placeholder="corrects no."
            value={corrects}
            onChange={(e) => {
              setCorrects(e.target.value);
              clearError();
            }}
          />{' '}
          <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
            {editing === null ? 'Add claim' : 'Save claim'}
          </button>
          {(invalid || (save.isError && refused === null)) && (
            <span data-testid="claim-form-error" role="alert">
              {' '}
              {invalid
                ? 'The amount must have up to two decimals; a negative amount must name the number of the settled claim it corrects.'
                : save.error instanceof HttpError && save.error.status === 409 && save.error.body.includes('retired')
                  ? `${person.name} is retired from ${person.retiredFrom}: a claim cannot be dated after it.`
                  : save.error instanceof HttpError && save.error.body.includes('correction')
                    ? `A correction must name a settled claim of ${person.name}.`
                  : 'Could not save this claim.'}
            </span>
          )}
        </form>
        <ul data-testid="claim-list">
          {claims.map((c) => (
            <li key={c.id} data-testid={`claim-row-${c.id}`}>
              <input
                type="checkbox"
                data-testid="claim-select"
                aria-label="Select claim"
                checked={selected.includes(c.id)}
                onChange={(e) =>
                  setSelected(e.target.checked ? [...selected, c.id] : selected.filter((id) => id !== c.id))
                }
              />{' '}
              <span data-testid="claim-amount">{c.amount}</span>{' '}
              <span data-testid="claim-date">{c.date}</span>{' '}
              <span data-testid="claim-period">{periodOf(periods, c.date)?.name ?? ''}</span>{' '}
              <span data-testid="claim-note">{c.note}</span>{' '}
              <span data-testid="claim-due">{showDue(claimDueCents(c, floor, rateOn(rates, gradeOn(person, c.date), c.date), lateBy))}</span>{' '}
              <span data-testid="claim-number">{c.number ?? ''}</span>{' '}
              <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
              <span data-testid="claim-status">{c.status}</span>{' '}
              <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
              <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-due-by">{dueBy(c, terms)}</span>{' '}
              <span data-testid="claim-overdue">{overdue(c, terms, today) ? 'yes' : 'no'}</span>{' '}
              {ACTIONS.map((action) => (
                <span key={action}>
                  {action === 'reject' && (
                    <>
                      <input
                        data-testid="claim-reject-reason"
                        aria-label="Reason for rejecting"
                        placeholder="reason"
                        value={reasons[c.id] ?? ''}
                        onChange={(e) => {
                          setReasons({ ...reasons, [c.id]: e.target.value });
                          if (refused?.id === c.id) setRefused(null);
                        }}
                      />{' '}
                    </>
                  )}
                  <button
                    type="button"
                    data-testid={`claim-${action}`}
                    disabled={changeStatus.isPending}
                    onClick={() => {
                      if (action === 'reject' && (reasons[c.id] ?? '').trim() === '') {
                        // Refused here, before anything is sent: the store is untouched.
                        setRefused({ id: c.id, message: NO_REASON });
                        return;
                      }
                      changeStatus.mutate({ id: c.id, action, reason: action === 'reject' ? (reasons[c.id] ?? '').trim() : undefined });
                    }}
                  >
                    {ACTION_LABELS[action]}
                  </button>{' '}
                </span>
              ))}
              <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
                Edit
              </button>
              {editing === c.id && (
                <>
                  {' '}
                  <button type="button" data-testid="claim-cancel" onClick={cancel}>
                    Cancel
                  </button>
                </>
              )}
              {refused?.id === c.id && (
                <span data-testid="claim-error" role="alert">
                  {' '}
                  {refused.message}
                </span>
              )}
            </li>
          ))}
        </ul>
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({
    order: 10,
    Component: () => (
      <>
        <th>Claimed</th>
        <th>Due</th>
        <th>Overdue</th>
        <th>Overdue due</th>
        <th>Claims</th>
      </>
    ),
  }),
  PersonCells.fill({ order: 10, Component: PersonClaims }),
];

